// What happens when you press Run:
//
//   Main.java        your code, text you can read
//        |
//        |   javac  (the compiler: checks and translates)
//        v
//   Main.class       bytecode, instructions for the JVM
//        |
//        |   java   (the JVM: runs the bytecode)
//        v
//   output in the terminal

public class Main {
    public static void main(String[] args) {
        System.out.println("Compiled, then run.");
    }
}

